    DataSchema dataSchema = mock(DataSchema.class);
    List<String> selectionColumns = SelectionOperatorUtils.getSelectionColumns(QueryContextConverterUtils.getQueryContextFromSQL("SELECT add(foo, 1), sub(bar, 2), foobar FROM testTable"), dataSchema);
